3: 
4: @Injectable({
5:     providedIn: 'root',
6: })
7: export class AuthGuard implements CanActivate {
8: 
9:     constructor() { }
10: 
11:     canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
12:         const menuInfo = localStorage.getItem('menu');
13:         const menuPermisos = menuInfo ? JSON.parse(atob(menuInfo)) : null;
14:         const fullUrl = window.location.href;
15:         const url = new URL(fullUrl);
16:         const path = url.pathname;
17: 
18:         // Obtener parámetros de la ruta
19:         const params = route.params;
20: 
21:         if (menuPermisos != null) {
22:             // Pasar tanto la URL como los parámetros a la función de verificación
23:             if (checkUrlExists(menuPermisos, path, params)) {
24:                 return true;
25:             }
26:         }
27: 
28:         // this.AlertService.showErrorAlert('Error de acceso');
29:         return false;
30:     }
31: 
32:     canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
33:         return this.canActivate(route, state);
34:     }
35: }
36: 
37: // Recorrer el menú para verificar si la URL y los parámetros existen
38: function checkUrlExists(menuItems: any, targetUrl: string, params: any) {
39:     return menuItems.some((item: any) => {
40:         // Verificar la URL y los parámetros
41:         if (item.Url === targetUrl && checkParams(item.Params, params)) {
42:             return true;
43:         }
44:         if (item.Opciones && item.Opciones.length > 0) {
45:             return checkUrlExists(item.Opciones, targetUrl, params);
46:         }
47:         return false;
48:     });
49: }
50: 
51: // Verificar los parámetros de la ruta
52: function checkParams(expectedParams: any, actualParams: any): boolean {
53:     if (!expectedParams) {
54:         return true; // No se requieren parámetros específicos
55:     }
56:     for (let key in expectedParams) {
57:         if (expectedParams[key] !== actualParams[key]) {
58:             return false; // Un parámetro no coincide
59:         }
60:     }
61:     return true; // Todos los parámetros coinciden
62: }

